#include "TestSupport.h"
#include "DspStageRuntime.h"
int main(){auto s=session(1);std::string error;StageBusWin32 source,render;DspStageRuntime dsp;CHECK(source.create(s,error));CHECK(dsp.attach(s,error));CHECK(render.open(dsp.outputSession(),error));auto* raw=static_cast<StageBusSessionHeader*>(render.address());auto* hb=reinterpret_cast<volatile LONG64*>(static_cast<unsigned char*>(render.address())+448);InterlockedExchange64(hb,0);CHECK(raw->consumer_pid!=0);CHECK(dsp.peersAlive(qpc()));render.heartbeat(qpc());auto sampled=qpc();Sleep(2);source.heartbeat(qpc());render.heartbeat(qpc());CHECK(dsp.peersAlive(sampled));source.heartbeat(qpc()-frequency()*2);CHECK(!dsp.peersAlive(qpc()));std::cout<<"PASS heartbeat updated after caller timestamp accepted; truly stale peer rejected\n";}
